package com.example.demo; import com.example.demo.model.User; import com.example.demo.repository.UserRepository; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; @SpringBootTest class UserCrudTest { @Autowired UserRepository r; @Test void crud(){r.deleteAll(); User u1=r.save(new User("Rahul Kumar","rahul@aditya.edu.in")); User u2=r.save(new User("Ananya Sen","ananya@aditya.edu.in")); System.out.println("CREATE: "+u1); System.out.println("READ: "+r.findAll()); u1.setName("Rahul Updated"); r.save(u1); System.out.println("UPDATE: "+r.findById(u1.getId()).orElseThrow()); r.deleteById(u2.getId()); System.out.println("DELETE completed; remaining: "+r.findAll());} }